function validate([derived]) {
  if (!Array.isArray(derived) || derived.length < 1 || derived.length > 100000) return 'derived needs 1 to 10^5 values.';
  if (derived.some(v => v !== 0 && v !== 1)) return 'Every value in derived is 0 or 1.';
  return null;
}

