function doesValidArrayExist(derived) {
  const n = derived.length;
  // Fix the first bit, rebuild the rest from the forward rule, then test the wrap-around pair.
  for (const start of [0, 1]) {
    const original = [start];
    for (let i = 0; i + 1 < n; i++) original.push(original[i] ^ derived[i]);
    let matches = true;
    for (let i = 0; i < n; i++) {
      if ((original[i] ^ original[(i + 1) % n]) !== derived[i]) matches = false;
    }
    if (matches) return true;
  }
  return false;
}

