function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const density = rand();
  return [Array.from({ length: n }, () => (rand() < density ? 1 : 0))];
}
